entries[127111] = { ["name"] = "Freeze", ["text"] = "12% of base mana 45 yd range\nInstant 25 sec cooldown\nBlasts enemies in a 8 yard radius from your current target for [source value] Frost damage and freezes them in place for up to 8 sec. Damage caused may interrupt the effect. [ Fingers of Frost : Grants the Mage a charge of Fingers of Frost for each target hit by Freeze ]", ["unresolvedValues"] = true }
