entries[127115] = { ["name"] = "Lord Blastington's Scope of Doom", ["text"] = "1.5 sec cast 5\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nGhost Iron Bolts (18), Primordial Ruby (2), Spirit of Harmony\nLord Blastington's Scope of Doom\n85\nUse: Permanently attaches Lord Blastington's special scope to a ranged weapon, sometimes increasing Agility by 1800 for 10 sec when dealing damage with ranged attacks.\n\nAttaching this scope to a ranged weapon causes it to become soulbound." }
entries[127116] = { ["name"] = "Mirror Scope", ["text"] = "1.5 sec cast 2\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nGhost Iron Bolts (4), Lapis Lazuli (2)\nMirror Scope\n85\nUse: Permanently attaches a mirrored scope to a ranged weapon, sometimes increases critical strike by 900 for 10 sec when dealing damage with ranged attacks.\n\nAttaching this scope to a ranged weapon causes it to become soulbound." }
entries[127117] = { ["name"] = "Lightweight Retinal Armor", ["text"] = "1.5 sec cast 5\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nLiving Steel (6), River's Heart , Ghost Iron Bolts (6)\nLightweight Retinal Armor\nBinds when picked up\nHead Cloth\n1733 Armor\n+1,522 Stamina\n+855 Intellect\n\nMeta Socket\nCogwheel Socket\nCogwheel Socket\nSocket Bonus: + 180 Intellect\n\nDurability 100 / 100\n87\nRequires Engineering\n(600)" }
