entries[127127] = { ["name"] = "G91 Landshark", ["text"] = "1.5 sec cast 2\nTools: Gyromatic Micro-Adjustor\nReagents:\nGhost Iron Bolts (2), High-Explosive Gunpowder (2)\n(3)\n85\nUse: Inflicts 37500 Fire damage to an enemy up to 45 yards away, as well as any enemies within 10 yards of the primary target. (1 Min Cooldown)" }
entries[127128] = { ["name"] = "Goblin Dragon Gun, Mark II", ["text"] = "1.5 sec cast 2\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nGhost Iron Bolts (3), High-Explosive Gunpowder (8)\n85\nUse: Unleash a gout of lightning, dealing 4500 Nature damage to targets in a 10 yard cone in front of the caster every 0.5 sec for 4 sec.\n\nMay walk while casting. (30 Sec Cooldown)\n50 Charges" }
entries[127129] = { ["name"] = "Blingtron 4000", ["text"] = "1.5 sec cast 5\nTools: Arclight Spanner , Blacksmith Hammer\nReagents:\nLiving Steel (4), Trillium Bar (4), Ghost Iron Bar (4), Vermilion Onyx (4), Wild Jade (4), Spirit of Harmony (4)\nBlingtron 4000\nBinds when picked up\nToy\nRequires Engineering\n(600)\nUse: Assembles the incredible Blingtron 4000, a robot of infinite wealth. Bling, as he likes to be called, will give out a random gift to anyone who talks to him, but only once per day. Lasts 10 min. (4 Hrs Cooldown)" }
entries[127130] = { ["name"] = "Mist-Piercing Goggles", ["text"] = "1.5 sec cast 5\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nGhost Iron Bolts (8), Spirit of Harmony (2)\nMist-Piercing Goggles\nBinds when equipped\nHead\nEquip: Allows you to see additional mining nodes and herbs while in Pandaria.\n\"While these goggles are very fashionable, they don't need to be worn to receive their special benefit.\"" }
entries[127131] = { ["name"] = "Thermal Anvil", ["text"] = "1.5 sec cast 3\nTools: Blacksmith Hammer\nReagents:\nHigh-Explosive Gunpowder (8), Ghost Iron Bolts (6)\nUse: Places a Thermal Anvil at your feet, granting anyone nearby the use of both an anvil and a forge. Lasts 5 min. (5 Min Cooldown)\n20 Charges" }
entries[127132] = { ["name"] = "Wormhole Generator: Pandaria", ["text"] = "1.5 sec cast 5\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nTrillium Bar (12), Spirit of Harmony (2)\nWormhole Generator: Pandaria\nBinds when used\nToy\nRequires Engineering\n(500)\nUse: Teleports you to somewhere in Pandaria. The exact location is difficult to predict, but will likely be far away. (15 Min Cooldown)\n\"There is a tiny note on the side: Wheeeeeeeeeee!\"" }
entries[127134] = { ["name"] = "Ghost Iron Dragonling", ["text"] = "1.5 sec cast 5\nTools: Arclight Spanner , Blacksmith Hammer\nReagents:\nWindwool Cloth (12), Ghost Iron Bolts (8), High-Explosive Gunpowder (4)\nGhost Iron Dragonling\nBinds when equipped\nUnique-EquippedTrinket\nCogwheel Socket\nCogwheel Socket\nCogwheel Socket\n\n87\nEquip: Your attacks have a chance to summon a Ghost Iron Dragonling to fight with you for 20 sec. (Proc chance: 25%, 1m cooldown)" }
entries[127135] = { ["name"] = "Mechanical Pandaren Dragonling", ["text"] = "1.5 sec cast 5\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nGhost Iron Bar (4), Trillium Bar (6), Spirit of Harmony (2)\nMechanical Pandaren Dragonling\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss your whelpling." }
entries[127136] = { ["name"] = "Big Game Hunter", ["text"] = "1.5 sec cast 3\nTools: Blacksmith Hammer , Gyromatic Micro-Adjustor\nReagents:\nGhost Iron Bolts (12), Hair Trigger , Walnut Stock , Mirror Scope\nBig Game Hunter\nBinds when equipped\nRanged Gun\n3,354 - 6,229 Damage Speed 2.80\n(1,711 damage per second)\n+449 Agility\n+703 Stamina\n+ 321 Critical Strike\n+ 283 Haste\n\nRed Socket\nSocket Bonus: + 10 Agility\n\nDurability 100 / 100\n85" }
entries[127137] = { ["name"] = "Long-Range Trillium Sniper", ["text"] = "1.5 sec cast 5\nTools: Blacksmith Hammer , Gyromatic Micro-Adjustor\nReagents:\nTrillium Bar (12), Hair Trigger , Spirit of Harmony , Lord Blastington's Scope of Doom\nLong-Range Trillium Sniper\nBinds when equipped\nRanged Gun\n5,704 - 10,595 Damage Speed 2.80\n(2,911 damage per second)\n+717 Agility\n+1,195 Stamina\n+ 435 Hit\n\nYellow Socket\nSocket Bonus: + 10 Agility\n\nDurability 100 / 100\n90" }
entries[127138] = { ["name"] = "Depleted-Kyparium Rocket", ["text"] = "1.5 sec cast 5\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nLiving Steel (12), Kyparite (200), Orb of Mystery (3), High-Explosive Gunpowder (12), Spirit of Harmony (12), Ghost Iron Bolts (20)\nDepleted-Kyparium Rocket\nUnique\nMount\n20\nRequires\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nThe apex of goblin ingenuity! This mount changes depending on your Riding skill and location." }
entries[127139] = { ["name"] = "Geosynchronous World Spinner", ["text"] = "1.5 sec cast 5\nTools: Arclight Spanner , Gyromatic Micro-Adjustor\nReagents:\nLiving Steel (12), Trillium Bar (12), Spirit of Harmony (12), Ghost Iron Bolts (20), Orb of Mystery (3)\nGeosynchronous World Spinner\nUnique\nMount\n20\nRequires\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nA device that rotates the very world beneath you! This mount changes depending on your Riding skill and location." }
